import test from 'node:test';
import assert from 'node:assert/strict';
import { addCents } from './cents.mjs';

test('10 + 20 = 30 cents', () => {
  assert.equal(addCents(10, 20), 30);
});

test('1230 + 4200 + 4570 = 10000 cents', () => {
  assert.equal(addCents(1230, 4200, 4570), 10000);
});

export function addCents(...amounts) {
  return amounts.reduce((total, amount) => {
    if (!Number.isSafeInteger(amount)) {
      throw new TypeError('Each amount must be a safe integer in cents');
    }
    const next = total + amount;
    if (!Number.isSafeInteger(next)) {
      throw new RangeError('Total exceeds the safe integer range');
    }
    return next;
  }, 0);
}

